+++ b/scale.c
@@ -1,4 +1,14 @@
 /* Scale a raw ADC count by a power of two. */
 int scale(int raw, int shift) {
-  return raw << shift;
+  int s = shift;
+  if (s < 0) s = 0;
+  if (s > 15) s = 15;
+  long long val = (long long)raw * (1LL << s);
+  long long max_val = 2147483647LL;
+  long long min_val = -2147483648LL;
+  if (val > max_val) {
+    return (int)max_val;
+  } else if (val < min_val) {
+    return (int)min_val;
+  }
+  return (int)val;
 }

